INSERT INTO `tb_blog` VALUES
(1, 1, 1, '回民街老孙家泡馍，掰馍半小时的仪式感谁懂🍜', '/imgs/blogs/0/0/feb2a83e-5646-46c0-a982-5e43fed31b22.jpg', '来西安第一顿必须是泡馍！<br/>老孙家在回民街开了几十年，饭点要排队但值得～<br/><br/>🫓掰馍是关键：馍要掰到黄豆大小，阿姨才会点头收碗<br/>🍲汤头浓而不腻，羊肉软烂不膻，糖蒜解腻绝配<br/>💰人均45，本地人和游客都认的老字号<br/><br/>📍北院门步行街118号<br/>⏰8:00-21:30<br/>#西安美食 #回民街 #羊肉泡馍', 128, 45, '2026-08-05 12:30:00', '2026-08-05 12:30:00'),
(2, 3, 2, '长安大排档汉服夜宴，一秒穿越回大唐🏮', '/imgs/blogs/0/5/e3e7c9e7-6654-4065-b47a-b86eb4541c33.jpg', '不夜城的宝藏陕菜馆子！<br/><br/>🏮环境：唐风装潢配灯笼，服务员穿汉服，拍照出片率100%<br/>🍗葫芦鸡外酥里嫩，biangbiang面宽到像裤带<br/>🎶晚上有皮影戏和秦腔表演，边吃边看很沉浸<br/><br/>建议傍晚去，吃完正好逛不夜城夜景～<br/>📍雁塔南路不夜城步行街北段', 96, 32, '2026-08-08 20:15:00', '2026-08-08 20:15:00'),
(3, 4, 1, '小寨赛格这口肉夹馍，馍酥得掉渣🥙', '/imgs/blogs/0/7/fe1b426e-48b5-4ec9-82b8-a953e564c992.jpg', '老潼关的馍是千层酥皮的，和普通白吉馍完全两种口感！<br/><br/>一口下去咔嚓响，肉汁渗进酥皮里绝了<br/>肥瘦相间最香，纯瘦会柴，记得跟老板说"肥瘦"<br/>配冰峰是西安人标配三秦套餐🍊<br/><br/>📍小寨赛格B2层<br/>💰人均25管饱', 87, 19, '2026-08-10 13:40:00', '2026-08-10 13:40:00'),
(4, 2, 3, '贾三灌汤包先吸汤再吃包，烫嘴警告⚠️', '/imgs/blogs/1/12/ab329e30-b4e1-446e-993b-b00be783f142.jpg', '北院门总店这家灌汤包吃了十几年！<br/><br/>🥟正确吃法：先咬小口→吸汤→蘸醋→一口吞<br/>汤汁清亮不腻，皮薄得透光<br/>牛肉馅最经典，羊肉馅更鲜<br/><br/>⚠️第一次吃一定先放凉30秒，烫到舌头别怪我没提醒<br/>📍北院门街93号（回民街内）', 76, 21, '2026-08-12 11:50:00', '2026-08-12 11:50:00'),
(5, 8, 2, '不夜城民谣酒吧，听了三小时不舍得走🎸', '/imgs/blogs/1/2/38f7e67d-7b26-41fd-bcf5-eebf71914230.jpg', '逛不夜城走累了，拐进这家民谣酒吧歇脚<br/>结果一听就是三个小时😂<br/><br/>🎸驻唱歌手水平在线，每首都像在讲西安的故事<br/>🍺精酿推荐"长安月色"，麦香浓郁回甘<br/>🏮露台位能直接看到大雁塔夜景<br/><br/>人均110，胜在氛围感拉满<br/>📍不夜城步行街中段', 64, 15, '2026-08-13 22:30:00', '2026-08-13 22:30:00'),
(6, 9, 1, '城墙根下的精酿，配着南门夜景干杯🍻', '/imgs/blogs/1/2/4a7b496b-2a08-4af7-aa95-df2c3bd0ef97.jpg', '永宁门瓮城旁边的小酒馆，位置绝了<br/><br/>傍晚先上城墙看日落，下来直接进店<br/>🍺招牌IPA果香浓郁，女生可以试荔枝小麦<br/>🌃窗外就是亮灯的城墙，本地人夜生活聚集地<br/><br/>人均85，比不夜城的酒吧更local<br/>📍南门瓮城西侧环城路', 58, 12, '2026-08-14 21:10:00', '2026-08-14 21:10:00'),
(7, 5, 3, '永兴坊的麻酱凉皮，芝麻酱香到舔碗🥣', '/imgs/blogs/0/0/feb2a83e-5646-46c0-a982-5e43fed31b22.jpg', '永兴坊这家凉皮和回民街的完全两个流派<br/><br/>西安凉皮分两派：米皮清爽/面皮筋道<br/>这家的麻酱凉皮酱香浓郁，辣子香而不燥<br/>配一碗冰镇醪糟，夏天吃太爽了<br/><br/>💰人均20，性价比之王<br/>📍中山门内永兴坊街区', 52, 9, '2026-08-15 14:20:00', '2026-08-15 14:20:00'),
(8, 6, 2, '钟楼德发长饺子宴，一颗饺子包尽长安🥟', '/imgs/blogs/0/5/e3e7c9e7-6654-4065-b47a-b86eb4541c33.jpg', '百年老字号德发长，就在钟鼓楼广场旁边！<br/><br/>🥟饺子宴有二十多种花样：金鱼饺、蝴蝶饺、小笼饺<br/>慈禧太后同款"珍珠饺子"，一颗只有小指甲盖大<br/>汤饺推荐酸汤水饺，酸辣开胃<br/><br/>吃完出门就是钟楼夜景，动线完美<br/>📍西大街钟鼓楼广场北侧', 69, 17, '2026-08-16 19:00:00', '2026-08-16 19:00:00'),
(9, 15, 3, '带娃大雁塔半日游，亲子乐园救了我🛝', '/imgs/blogs/0/7/fe1b426e-48b5-4ec9-82b8-a953e564c992.jpg', '带四岁娃逛大雁塔，逛到一半娃开始闹<br/>搜到南广场这家亲子乐园，救命了！<br/><br/>🛝海洋球+攀爬架+沙池，放电两小时不重样<br/>🧑‍🍳还有小厨师体验课，做的小饼干能带走<br/>💰80不限时，家长休息区能看到娃<br/><br/>📍大雁塔南广场西侧<br/>#西安遛娃 #亲子乐园', 45, 11, '2026-08-17 16:30:00', '2026-08-17 16:30:00'),
(10, 7, 1, '钟楼唐宫KTV团建实录，包厢大得像剧场🎤', '/imgs/blogs/1/12/ab329e30-b4e1-446e-993b-b00be783f142.jpg', '公司团建选了这家，号称钟楼最大的KTV<br/><br/>🎤唐风主题包厢，星空顶+全息投影<br/>🍢小食拼盘管够，歌单很新，英文歌也不缺<br/>💰人均98畅玩3小时，性价比可以<br/><br/>位置在粉巷口，喝完还能逛南大街<br/>📍南大街粉巷口唐宫大厦F4', 39, 8, '2026-08-18 23:00:00', '2026-08-18 23:00:00'),
(11, 13, 2, '大唐足道体验记：逛城墙逛废的双脚回血了🦶', '/imgs/blogs/1/2/38f7e67d-7b26-41fd-bcf5-eebf71914230.jpg', '城墙骑完一整圈13.7公里，双脚已经不是自己的了<br/>搜到这家足道，位置就在永宁门旁边<br/><br/>💆60分钟古法足疗+肩颈按摩<br/>🍵送果盘和茯茶，环境是禅意风<br/>技师手法专业，按完确实轻松不少<br/><br/>💰138套餐，游客救星<br/>📍南关正街88号', 33, 6, '2026-08-19 20:45:00', '2026-08-19 20:45:00'),
(12, 18, 3, '芙蓉园旁边的音乐酒吧，夜景不输不夜城🌃', '/imgs/blogs/1/2/4a7b496b-2a08-4af7-aa95-df2c3bd0ef97.jpg', '看《大唐追梦》演出前发现的宝藏酒吧<br/><br/>🌃露台正对芙蓉园，水面灯光倒影绝美<br/>🎷爵士乐队现场，氛围比不夜城安静<br/>🍸特调"芙蓉醉"颜值超高，甜口适合女生<br/><br/>人均95，适合约会和拍照<br/>📍芙蓉西路芙蓉新天地', 41, 9, '2026-08-20 21:30:00', '2026-08-20 21:30:00');
