-- ============================================================
-- 长安文旅探店助手 · 西安版种子数据（阶段 6）
-- 用途：全站数据西安化（TRUNCATE + INSERT，幂等可重跑）
-- 回滚：apply_xian_data.py 执行前自动建 backup_* 表
-- 质量保障：
--   1) prompt 约束（字段规则：type_id∈1..10、score×10、外键一致）
--   2) 脚本校验（apply 脚本执行后打印计数/外键/坐标范围校验）
--   3) 人工抽查（商圈名与坐标逐一对照真实地图）
-- 坐标：真实西安商圈基准坐标 ±0.002 随机偏移（约 200 米），
--       保证"按距离排序"演示真实可信——AI 生成数据最容易翻车的点。
-- ============================================================

TRUNCATE TABLE `tb_voucher_order`;
TRUNCATE TABLE `tb_blog_comments`;
TRUNCATE TABLE `tb_seckill_voucher`;
TRUNCATE TABLE `tb_voucher`;
TRUNCATE TABLE `tb_blog`;
TRUNCATE TABLE `tb_shop`;

